      sha256 "8df81c0645522ba6cedf8e86f953984f517c41ae79963bfd8a3dfb82797527b3"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.18/open-walnut-0.6.18-darwin-x64.tar.gz", using: :nounzip
      sha256 "ea6c4c2cb5adf7a0b1d49cfa4e08c542bcb7a22945aa8d0e384f3410f117d906"
    end
  end

  on_linux do
    on_arm do
